static const z_t83_t _zs77 = { .data = _zs77_d, .size = 18 };
static const char _zs78_d[] = "\nZC_CC=";
static const z_t83_t _zs78 = { .data = _zs78_d, .size = 7 };
static const char _zs79_d[] = "\nZC_CC_MODE=";
static const z_t83_t _zs79 = { .data = _zs79_d, .size = 12 };
static const char _zs80_d[] = "\nZC_TCC=";
